using Hyper.Domain.Entities.Integrations; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace Hyper.Infrastructure.Data.Configurations; public sealed class BoothAccountingMappingConfiguration:IEntityTypeConfiguration<BoothAccountingMapping>{public void Configure(EntityTypeBuilder<BoothAccountingMapping>b){b.ToTable("BoothAccountingMappings");b.HasKey(x=>x.Id);b.Property(x=>x.TenantId).HasMaxLength(30).IsRequired();b.Property(x=>x.BasalamProductId).HasMaxLength(128).IsRequired();b.Property(x=>x.BasalamSku).HasMaxLength(128);b.Property(x=>x.AccountingCode).HasMaxLength(50);b.HasIndex(x=>new{x.ShopId,x.BasalamProductId}).IsUnique();}}
